import React from "react";
import {
  FaMapMarkerAlt,
  FaCalendarAlt,
  FaTimes,
} from "react-icons/fa";
import DatePicker from "react-multi-date-picker";
import persian from "react-date-object/calendars/persian";
import persian_fa from "react-date-object/locales/persian_fa";

const API_URL = "https://iranaserviceapp.ir/test/api";

class FilterModal extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      animateIn: false,
      provinces: [],
      loadingProvinces: false,
    };
  }

  componentDidMount() {
    requestAnimationFrame(() => {
      this.setState({
        animateIn: true,
      });
    });

    this.getProvinces();
  }

  getProvinces = () => {
    this.setState({
      loadingProvinces: true,
    });

    fetch(`${API_URL}/cities`, {
      method: "GET",
      headers: {
        Accept: "application/json",
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error(
            "خطا در دریافت استان‌ها"
          );
        }

        return response.json();
      })
      .then((data) => {
        console.log("PROVINCES API:", data);

        let provinces = [];

        if (Array.isArray(data.states)) {
          provinces = data.states;
        } else if (
          Array.isArray(data.provinces)
        ) {
          provinces = data.provinces;
        } else if (
          Array.isArray(data.data)
        ) {
          provinces = data.data;
        }

        this.setState({
          provinces,
          loadingProvinces: false,
        });
      })
      .catch((error) => {
        console.error(
          "GET PROVINCES ERROR:",
          error
        );

        this.setState({
          provinces: [],
          loadingProvinces: false,
        });
      });
  };

  renderField = ({
    icon,
    children,
  }) => {
    return (
      <div
        className="d-flex align-items-center gap-2 border rounded-3 px-3 mb-3 bg-white"
        style={{
          minHeight: "58px",
          transition:
            "border-color .25s ease, box-shadow .25s ease",
        }}
      >
        {children}

        {icon}
      </div>
    );
  };

  render() {
    const {
      isOpen,
      onClose,
      onApply,
      province,
      startDate,
      endDate,
      onProvinceChange,
      onStartDateChange,
      onEndDateChange,
    } = this.props;

    const {
      animateIn,
      provinces,
      loadingProvinces,
    } = this.state;

    if (!isOpen) {
      return null;
    }

    return (
      <div dir="rtl">
        {/* Overlay */}

        <div
          onClick={onClose}
          className="position-fixed top-0 start-0 w-100 h-100"
          style={{
            background:
              "rgba(0, 0, 0, .45)",
            zIndex: 1040,
            opacity: animateIn ? 1 : 0,
            transition:
              "opacity .35s ease",
          }}
        />

        {/* Bottom Sheet */}

        <div
          className="position-fixed bottom-0 bg-white rounded-top-4 px-3 pt-3 pb-4"
          style={{
            zIndex: 1050,
            width: "100%",
            maxWidth: "480px",
            left: "50%",
            transform: animateIn
              ? "translate(-50%, 0)"
              : "translate(-50%, 100%)",
            transition:
              "transform .4s cubic-bezier(.22,1,.36,1)",
            boxShadow:
              "0 -8px 30px rgba(0,0,0,.12)",
          }}
        >
          {/* Header */}

          <div className="d-flex justify-content-start mb-4">
            <button
              type="button"
              onClick={onClose}
              className="btn btn-light rounded-circle d-flex align-items-center justify-content-center"
              style={{
                width: "38px",
                height: "38px",
              }}
            >
              <FaTimes size={15} />
            </button>
          </div>

          {/* استان */}

          {this.renderField({
            icon: (
              <FaMapMarkerAlt
                size={17}
                className="text-secondary"
              />
            ),
            children: (
              <select
                value={province}
                onChange={
                  onProvinceChange
                }
                disabled={
                  loadingProvinces
                }
                className="form-select border-0 bg-transparent shadow-none text-end flex-grow-1"
                style={{
                  fontSize: "14px",
                }}
              >
                <option value="">
                  {loadingProvinces
                    ? "در حال دریافت استان‌ها..."
                    : "استان"}
                </option>

                {provinces.map(
                  (item) => (
                    <option
                      key={item.id}
                      value={item.id}
                    >
                      {item.name}
                    </option>
                  )
                )}
              </select>
            ),
          })}

          {/* تاریخ از */}

          {this.renderField({
            icon: (
              <FaCalendarAlt
                size={17}
                className="text-secondary"
              />
            ),
            children: (
              <DatePicker
                value={startDate}
                onChange={
                  onStartDateChange
                }
                calendar={persian}
                locale={persian_fa}
                calendarPosition="bottom-right"
                format="YYYY/MM/DD"
                placeholder="از تاریخ"
                inputClass="form-control border-0 bg-transparent shadow-none text-end"
                containerStyle={{
                  width: "100%",
                }}
                style={{
                  width: "100%",
                  height: "40px",
                  border: "none",
                  boxShadow: "none",
                  fontSize: "14px",
                  textAlign: "right",
                }}
              />
            ),
          })}

          {/* تاریخ تا */}

          {this.renderField({
            icon: (
              <FaCalendarAlt
                size={17}
                className="text-secondary"
              />
            ),
            children: (
              <DatePicker
                value={endDate}
                onChange={
                  onEndDateChange
                }
                calendar={persian}
                locale={persian_fa}
                calendarPosition="bottom-right"
                format="YYYY/MM/DD"
                placeholder="تا تاریخ"
                inputClass="form-control border-0 bg-transparent shadow-none text-end"
                containerStyle={{
                  width: "100%",
                }}
                style={{
                  width: "100%",
                  height: "40px",
                  border: "none",
                  boxShadow: "none",
                  fontSize: "14px",
                  textAlign: "right",
                }}
              />
            ),
          })}

          {/* Apply */}

          <button
            type="button"
            onClick={onApply}
            className="btn btn-primary w-100 rounded-3 mt-2"
            style={{
              height: "56px",
              border: "none",
              background: "#5d4ab3",
              transition:
                "transform .2s ease, box-shadow .2s ease",
            }}
          >
            اعمال فیلتر
          </button>
        </div>
      </div>
    );
  }
}

export default FilterModal;
